# Verify the solution
solution = [5, 6, 2, 3, 1, 9, 6, 8, 7, 8, 9, 4, 7, 5, 5, 2, 4, 0, 3, 0, 1, 1, 2, 3, 4, 0, 7, 8, 6, 9, 8, 6, 5, 4, 9, 7, 3, 6, 0, 8, 4, 9, 3, 1, 5, 9, 3, 8, 0, 4, 0, 1, 2, 2, 1, 7, 6, 5, 7, 2, 8, 5, 1, 8, 3, 0, 6, 6, 1, 0, 3, 2, 2, 7, 6, 4, 4, 9, 9, 4, 0, 1, 2, 3, 5, 5, 8, 7, 7, 9, 8, 1, 4, 7, 2, 8, 9, 0, 6, 5, 1, 6, 3, 3, 5, 0, 4, 7, 4, 2, 0, 1, 2, 3, 5, 6, 9, 8, 7, 9, 8, 3, 8, 0, 7, 1, 6, 2, 1, 4, 4, 3, 4, 9, 0, 9, 2, 9, 5, 1, 0, 5, 2, 3, 6, 5, 7, 6, 7, 8, 8, 6, 4, 1, 5, 4, 3, 9, 9, 7, 8, 0, 1, 2, 5, 3, 7, 9, 2, 0, 0, 1, 2, 3, 4, 5, 7, 6, 8, 6, 7, 3, 4, 2, 2, 6, 6, 0, 5, 4, 5, 0, 1, 6, 3, 1, 2, 8, 1, 9, 7, 0, 3, 4, 5, 7, 8, 8, 9, 9, 6, 6, 4, 2, 5, 1, 4, 3, 8, 7, 9, 7, 6, 0, 9, 8, 0, 1, 5, 3, 0, 1, 2, 3, 2, 4, 9, 5, 7, 8]

num_golfers = 30
num_groups = 10
group_size = 3
num_weeks = 8

# Parse solution into weeks
weeks = []
for w in range(num_weeks):
    week = solution[w*30:(w+1)*30]
    weeks.append(week)

# Check 1: All values in 0..9
for w in range(num_weeks):
    for p in range(num_golfers):
        assert 0 <= weeks[w][p] <= 9, f"Invalid group {weeks[w][p]} for golfer {p} in week {w}"

# Check 2: Each group has exactly 3 golfers each week
for w in range(num_weeks):
    group_counts = [0] * num_groups
    for p in range(num_golfers):
        group_counts[weeks[w][p]] += 1
    for g in range(num_groups):
        assert group_counts[g] == 3, f"Week {w}, group {g} has {group_counts[g]} golfers"

# Check 3: No pair of golfers is in the same group more than once
pair_weeks = {}
for w in range(num_weeks):
    # Group golfers by their group
    groups = {}
    for p in range(num_golfers):
        g = weeks[w][p]
        if g not in groups:
            groups[g] = []
        groups[g].append(p)

    # Check each group
    for g, golfers in groups.items():
        assert len(golfers) == 3, f"Week {w}, group {g} has {len(golfers)} golfers"
        for i in range(len(golfers)):
            for j in range(i+1, len(golfers)):
                p1, p2 = golfers[i], golfers[j]
                pair = (min(p1, p2), max(p1, p2))
                if pair in pair_weeks:
                    print(f"ERROR: Pair {pair} appears in weeks {pair_weeks[pair]} and {w}")
                pair_weeks[pair] = w

print("All checks passed!")
print(f"Total pairs covered: {len(pair_weeks)}")
print(f"Total possible pairs: {num_golfers * (num_golfers - 1) // 2}")
